import{_ as n,o as i,c as t,a2 as e}from"./chunks/framework.CqpfiAoK.js";const o=JSON.parse('{"title":"Kamus Istilah","description":"","frontmatter":{},"headers":[],"relativePath":"id/0090-术语词典.md","filePath":"id/0090-术语词典.md"}'),s={name:"id/0090-术语词典.md"};function d(r,a,u,k,m,l){return i(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="kamus-istilah" tabindex="-1">Kamus Istilah <a class="header-anchor" href="#kamus-istilah" aria-label="Permalink to &quot;Kamus Istilah&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Item</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>90</td></tr><tr><td>Modul</td><td>Lampiran dan Bahan Rujukan</td></tr><tr><td>Kata Kunci Inti</td><td>kamus istilah, konsep inti, definisi, terminologi terpadu, Hengyuanzhou</td></tr></tbody></table><h2 id="_1-penjelasan-istilah" tabindex="-1">1. Penjelasan Istilah <a class="header-anchor" href="#_1-penjelasan-istilah" aria-label="Permalink to &quot;1. Penjelasan Istilah&quot;">​</a></h2><p>Kamus ini memuat istilah-istilah inti dalam sistem pengaturan Peradaban Simbiosis Jangkar, bertujuan untuk menyatukan penggunaan istilah dalam seluruh dokumen dan memastikan konsistensi serta akurasi ekspresi konsep. Semua istilah diurutkan berdasarkan huruf pertama pinyin bahasa Mandarin, dan setiap istilah mencakup nama istilah, nama rujukan bahasa Inggris (jika ada), definisi, dan penjelasan singkat. Kamus ini adalah dokumen pembaruan dinamis, dan istilah baru akan terus ditambahkan seiring dengan perluasan sistem pengaturan.</p><h2 id="_2-tabel-istilah-inti" tabindex="-1">2. Tabel Istilah Inti <a class="header-anchor" href="#_2-tabel-istilah-inti" aria-label="Permalink to &quot;2. Tabel Istilah Inti&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No</th><th>Istilah</th><th>Definisi dan Penjelasan</th></tr></thead><tbody><tr><td>1</td><td>Jangkar</td><td>Simpul stabil dalam jaringan hukum, merupakan acuan koordinat untuk menjaga stabilitas hukum dimensi, mewujudkan koneksi antardimensi, dan penelusuran kembali waktu. Jangkar pada dasarnya adalah kondensat kepadatan tinggi dari hukum asal alam semesta pada posisi spasial tertentu, memiliki kemampuan pemeliharaan mandiri dan kalibrasi.</td></tr><tr><td>2</td><td>Peradaban Simbiosis Jangkar</td><td>Bentuk peradaban yang menggunakan mekanisme jangkar sebagai dasar teknis dan evolusi simbiosis sebagai konsep inti. Menentang sistem kultivasi predator, menganjurkan untuk mengembalikan hak pilihan nasib dan evolusi kepada semua makhluk, mewujudkan lebih banyak kerja lebih banyak hasil, lahir dan tumbuh mandiri, semua orang punya jalan, semua ras maju bersama.</td></tr><tr><td>3</td><td>Hengyuanzhou</td><td>Singkatan dari &quot;Wanling Hengmao Benyuan Zhou&quot;, merupakan seluruh alam semesta yang dihuni dan diperintah oleh Peradaban Simbiosis Jangkar. Merupakan wujud majemuk yang terdiri dari empat lapisan: dimensi materi, lapisan energi, domain kesadaran, dan jaringan hukum.</td></tr><tr><td>4</td><td>Wanling Hengmao Benyuan Zhou</td><td>Nama lengkap Hengyuanzhou. &quot;Wanling&quot; merujuk pada semua bentuk kehidupan yang memiliki potensi persepsi dan evolusi, &quot;Hengmao&quot; merujuk pada mekanisme jangkar yang menjaga keseimbangan alam semesta, &quot;Benyuan Zhou&quot; menekankan atribut esensial yang berlandaskan hukum asal dan berarah pada evolusi simbiosis.</td></tr><tr><td>5</td><td>Simbiosis</td><td>Salah satu konsep inti Peradaban Simbiosis Jangkar, merujuk pada evolusi bersama yang dicapai melalui kerja sama saling menguntungkan antara individu hidup, ras, dan peradaban yang berbeda, bukan evolusi predator dengan mengorbankan orang lain.</td></tr><tr><td>6</td><td>Sistem Kultivasi Predator</td><td>Cara kultivasi yang mewujudkan evolusi diri dengan memangsa energi, keberuntungan, bahkan asal dari yang lemah. Jenis sistem yang dengan tegas ditentang oleh Peradaban Simbiosis Jangkar, dianggap sebagai akar dari percepatan peningkatan entropi alam semesta dan seringnya terjadinya pemutusan peradaban.</td></tr><tr><td>7</td><td>Tiga Ratus Set Sistem Kultivasi Asal</td><td>Jalur kultivasi ortodoks yang diekstrak langsung dari hukum asal alam semesta dan diverifikasi oleh jangkar, berjumlah tiga ratus set, dibagi menjadi enam kategori: deduksi asal, siklus kehidupan, hukum ruang, peningkatan kesadaran, jaringan simbiosis, dan rekayasa terapan, masing-masing lima puluh set.</td></tr><tr><td>8</td><td>Tiga Dasar Asal</td><td>Tiga set sistem dasar pertama di antara tiga ratus set — Sistem Deduksi Iteratif (set ke-1), Sistem Siklus Kehidupan (set ke-2), Sistem Kontrol Hukum Ruang (set ke-3), yang merupakan dasar kultivasi semua sistem lainnya.</td></tr><tr><td>9</td><td>Sistem Deduksi Iteratif</td><td>Set ke-1 sistem kultivasi asal, dengan ciri inti peningkatan deduksi kultivasi seratus kali lipat, menggunakan aplikasi teknis Buah Perkalian untuk meningkatkan kemampuan deduksi seratus kali lipat, menekankan optimalisasi jalur kultivasi melalui deduksi, verifikasi, dan iterasi.</td></tr><tr><td>10</td><td>Sistem Siklus Kehidupan</td><td>Set ke-2 sistem kultivasi asal, dengan inti siklus sehat energi kehidupan, menekankan bahwa pertukaran energi antara kultivator itu sendiri dan lingkungan harus bersifat siklus, bukan predator.</td></tr><tr><td>11</td><td>Sistem Kontrol Hukum Ruang</td><td>Set ke-3 sistem kultivasi asal, dengan inti pemahaman dan kontrol hukum ruang, merupakan dasar kultivasi untuk aplikasi penting seperti interaksi antardimensi, konstruksi ruang terisolasi, dan teknologi cermin salinan.</td></tr><tr><td>12</td><td>Buah Perkalian</td><td>Buah Perkalian yang berasal dari dunia One Piece, diterapkan secara teknis di Hengyuanzhou, mampu meningkatkan kemampuan deduksi kultivator seratus kali lipat, merupakan alat bantu inti dari Sistem Deduksi Iteratif. Salah satu buff awal.</td></tr><tr><td>13</td><td>Mekanisme Kontrak Produksi Bersama</td><td>Mekanisme alokasi sumber daya Peradaban Simbiosis Jangkar, yang mengalokasikan sumber daya kultivasi alam semesta kepada individu atau kelompok dengan cara &quot;kontrak&quot;, dan kontraktor mendapatkan hak penggunaan sumber daya melalui kerja dan kontribusi, mewujudkan lebih banyak kerja lebih banyak hasil.</td></tr><tr><td>14</td><td>Strategi Aktivasi 20%</td><td>Tujuan strategis bertahap Peradaban Simbiosis Jangkar, pada tahap awal mengaktifkan 20% dari semua makhluk di alam semesta untuk menjadi yang terkuat tertinggi dimensi, menggunakan mereka sebagai tulang punggung untuk mendorong evolusi bersama 80% sisanya.</td></tr><tr><td>15</td><td>Yang Terkuat Tertinggi Dimensi</td><td>Yang kuat yang telah mencapai alam kultivasi yang sangat tinggi dan mampu menjaga stabilitas hukum satu dimensi sendirian. Merupakan objek pelatihan target dari Strategi Aktivasi 20%, dan juga merupakan kekuatan pemeliharaan penting dari jaringan jangkar.</td></tr><tr><td>16</td><td>Jaringan Hukum</td><td>Lapisan keempat dari struktur Hengyuanzhou, merupakan lapisan dasar operasi hukum asal alam semesta dan lapisan akar jangkar. Jaringan hukum mencakup seluruh alam semesta, dan merupakan dasar teknis dari semua operasi hukum (termasuk kontrol ruang, penelusuran kembali waktu, dan konversi energi).</td></tr><tr><td>17</td><td>Dimensi</td><td>Wilayah keberadaan yang didefinisikan oleh sekumpulan hukum yang relatif stabil, dengan kontinuitas ruang-waktu yang mandiri. Setiap dimensi memiliki konstanta fisik yang unik, kepadatan energi, kecepatan aliran waktu, dan aktivitas kesadaran.</td></tr><tr><td>18</td><td>Penghalang Hukum</td><td>Penghalang hukum yang memisahkan dimensi yang berdekatan, kekuatannya bergantung pada tingkat perbedaan parameter hukum antara dimensi yang berdekatan. Penyeberangan dimensi memerlukan penaklukan penghalang hukum.</td></tr><tr><td>19</td><td>Sidik Jari Hukum</td><td>Pengenal unik yang dihasilkan oleh operasi hash dari parameter hukum inti setiap dimensi, panjangnya 128 bit, merupakan salah satu parameter inti dari sistem koordinat dimensi.</td></tr><tr><td>20</td><td>Amati Terlebih Dahulu Kemudian Intervensi Terbatas</td><td>Prinsip operasi utama dari penelusuran kembali waktu dan arkeologi antardimensi, menuntut bahwa setiap penelusuran kembali atau arkeologi harus terlebih dahulu menyelesaikan tahap pengamatan murni, dan hanya setelah mengonfirmasi tidak ada risiko signifikan barulah intervensi terbatas dapat dilakukan.</td></tr><tr><td>21</td><td>Cermin Salinan</td><td>Perangkat salinan presisi tinggi berdasarkan hukum ruang, mampu melakukan salinan lengkap 1:1 pada wilayah target tanpa menyentuh objek asli, merupakan peralatan inti dari skema arkeologi jarak jauh.</td></tr><tr><td>22</td><td>Ruang Terisolasi</td><td>Wilayah hukum mandiri yang dibangun melalui teknologi kontrol hukum ruang, digunakan untuk menampung salinan arkeologi dan sebagai tempat kerja bagi arkeolog, sepenuhnya terpisah dari alam semesta eksternal oleh penghalang hukum.</td></tr><tr><td>23</td><td>Hanya Mengembalikan Pengetahuan</td><td>Prinsip inti dari protokol arkeologi, merujuk pada bahwa apa yang diperoleh dari objek target selama arkeologi hanya boleh berupa pengetahuan dan informasi abstrak, dan tidak boleh mengembalikan materi, energi, atau makhluk hidup apa pun.</td></tr><tr><td>24</td><td>Pemurnian Informasi</td><td>Proses teknis untuk sepenuhnya menghilangkan jejak hukum dimensi asal yang dibawa dalam informasi asli, hanya menyisakan konten semantik murni, merupakan tautan kunci untuk memastikan keamanan pengetahuan yang dikembalikan.</td></tr><tr><td>25</td><td>Paradoks Waktu</td><td>Fenomena kontradiksi diri dalam logika sebab-akibat yang disebabkan oleh perilaku intervensi selama operasi penelusuran kembali waktu, termasuk empat kategori: paradoks kakek, paradoks informasi, paradoks ontologis, dan paradoks peristiwa.</td></tr><tr><td>26</td><td>Rantai Sebab-Akibat</td><td>Struktur linier berkelanjutan dari sebab dan akibat antara peristiwa, merupakan konsep inti dari hukum waktu. Risiko inti dari operasi penelusuran kembali waktu adalah gangguan pada rantai sebab-akibat.</td></tr><tr><td>27</td><td>Konstitusi Simbiosis</td><td>Hukum dasar Peradaban Simbiosis Jangkar, memiliki kekuatan hukum tertinggi, menetapkan dasar peradaban anti-predator dan pro-simbiosis serta tujuh prinsip dasar konstitusi.</td></tr><tr><td>28</td><td>Kesetaraan Semua Ras</td><td>Salah satu dari tujuh prinsip dasar Konstitusi Simbiosis, merujuk pada bahwa semua bentuk kehidupan, tanpa memandang ras, tingkat kultivasi, atau asal-usul, adalah setara di hadapan hukum.</td></tr><tr><td>29</td><td>Kehidupan Aneh</td><td>Bentuk kehidupan yang tidak sesuai dengan definisi kehidupan konvensional dan memiliki bentuk keberadaan khusus, memerlukan identifikasi dan pengelolaan sesuai dengan tiga jenis proses penanganan standar.</td></tr><tr><td>30</td><td>Energi Aneh</td><td>Bentuk energi yang tidak sesuai dengan klasifikasi energi konvensional dan memiliki atribut serta pola perilaku khusus, memerlukan klasifikasi dan kontrol sesuai dengan tiga jenis proses penanganan standar.</td></tr><tr><td>31</td><td>Substitusi Kegelapan</td><td>Suatu bentuk kehidupan khusus, melibatkan masalah etika dari koeksistensi dua jiwa, memerlukan pengelolaan sesuai dengan pedoman etika dua jiwa dan empat jenis aturan penanganan cabang.</td></tr><tr><td>32</td><td>Etika Dua Jiwa</td><td>Pedoman etika untuk keadaan koeksistensi dua jiwa dalam Substitusi Kegelapan, intinya adalah menghormati hak masing-masing dari dua jiwa, melarang fusi paksa atau penghapusan salah satu pihak.</td></tr><tr><td>33</td><td>Lima Jenis Klasifikasi Peradaban Simbiosis</td><td>Lima jenis masyarakat simbiosis yang dibagi berdasarkan karakteristik peradaban dunia nyata: tipe intensif Asia Timur, tipe kesejahteraan Nordik, tipe plural Amerika Utara, tipe sosial Eropa kontinental, tipe mengejar ketertinggalan berkembang.</td></tr><tr><td>34</td><td>Jalur Peningkatan Empat Tahap</td><td>Rute empat tahap untuk peningkatan keseluruhan alam semesta Hengyuanzhou: fondasi realitas → pemberdayaan teknologi → evolusi kesadaran → simbiosis antarbintang.</td></tr><tr><td>35</td><td>Realitas sebagai Dasar</td><td>Salah satu posisi fundamental Peradaban Simbiosis Jangkar, merujuk pada bahwa dunia nyata adalah satu-satunya dunia nyata, dunia novel adalah eksperimen pemikiran palsu, yang fiktif tidak cukup dilengkapi dengan realitas, dan yang tidak ada dalam realitas diciptakan melalui peningkatan berdasarkan hukum.</td></tr><tr><td>36</td><td>Derajat Simbiosis</td><td>Indikator kuantitatif untuk mengevaluasi derajat integrasi suatu peradaban atau individu dengan jaringan simbiosis, mencakup berbagai dimensi seperti derajat berbagi sumber daya, frekuensi kerja sama, dan proporsi perilaku altruis.</td></tr><tr><td>37</td><td>Dewan Jangkar</td><td>Lembaga kekuasaan tertinggi Peradaban Simbiosis Jangkar, terdiri dari perwakilan semua ras secara proporsional, menjalankan kekuasaan legislatif dan kekuasaan pengambilan keputusan atas hal-hal penting.</td></tr><tr><td>38</td><td>Komite Eksekutif Simbiosis</td><td>Lembaga administratif tertinggi Peradaban Simbiosis Jangkar, bertanggung jawab atas pelaksanaan konstitusi dan hukum serta tata kelola sehari-hari.</td></tr><tr><td>39</td><td>Pengadilan Simbiosis</td><td>Lembaga yudikatif tertinggi Peradaban Simbiosis Jangkar, menjalankan kekuasaan peradilan secara mandiri, bertanggung jawab atas peninjauan inkonstitusionalitas dan persidangan kasus penting.</td></tr><tr><td>40</td><td>Biro Manajemen Dimensi</td><td>Lembaga khusus di bawah Dewan Jangkar, bertanggung jawab atas pemeliharaan bank total koordinat dimensi, persetujuan izin penyeberangan, manajemen arkeologi antardimensi, dan urusan lainnya.</td></tr></tbody></table><h2 id="_3-norma-penggunaan-istilah" tabindex="-1">3. Norma Penggunaan Istilah <a class="header-anchor" href="#_3-norma-penggunaan-istilah" aria-label="Permalink to &quot;3. Norma Penggunaan Istilah&quot;">​</a></h2><ol><li>Istilah-istilah yang dimuat dalam kamus ini adalah istilah standar, dan semua dokumen harus memprioritaskan penggunaan ekspresi standar dalam kamus ini.</li><li>Konsep yang sama harus menggunakan istilah yang sama dalam dokumen yang berbeda, dan tidak boleh mengganti sinonim secara sewenang-wenang.</li><li>Istilah baru yang dihasilkan dalam pengaturan baru harus segera diajukan ke komite istilah untuk ditinjau, dan setelah lulus peninjauan, akan ditambahkan ke kamus ini.</li><li>Jika definisi suatu istilah direvisi, versi terbaru dari kamus ini yang menjadi acuan, dan pada saat yang sama isi revisi harus dicatat dalam penjelasan versi dokumen.</li><li>Saat mengutip istilah, nama lengkap dapat digunakan pada kemunculan pertama, dan singkatan dapat digunakan kemudian, tetapi harus dipastikan bahwa makna dalam konteks jelas.</li></ol><h2 id="kesimpulan" tabindex="-1">Kesimpulan <a class="header-anchor" href="#kesimpulan" aria-label="Permalink to &quot;Kesimpulan&quot;">​</a></h2><p>Kamus istilah adalah batu penjuru linguistik dari seluruh sistem pengaturan. Sistem terminologi yang terpadu memastikan konsistensi konsep di antara seratus dokumen, memungkinkan pembaca untuk beralih dengan mulus antar modul yang berbeda tanpa ambiguitas pemahaman. Seiring dengan terus diperkaya dan ditingkatkannya sistem pengaturan, kamus ini akan terus diperbarui, dan selalu berfungsi sebagai sumber otoritatif istilah untuk semua dokumen.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>00-Tinjauan Umum Alam Semesta Hengyuanzhou</li><li>02-Definisi dan Esensi Asal Jangkar</li><li>99-Penjelasan Versi dan Pemeliharaan Dokumen</li></ul>',12)])])}const p=n(s,[["render",d]]);export{o as __pageData,p as default};
